namespace AvalynxOfficeEas\Service;

use AvalynxOfficeEas\Db\Model\CalendarEvent;
use AvalynxOfficeEas\Db\Model\CalendarEventException;

/**
 * Maps CalendarEvent models to EAS SyncAppointment objects and back.
 *
 * Every SyncAppointment field with a storage counterpart is mapped.
 * Deliberately unmapped: rtf (no RTF storage) and meetingrequest (meeting
 * request mails are not generated by this server).
 */
final class CalendarMapper
{
    /**
     * @return array{id: string, mod: string, flags: int, star: int}
     */
    public function stat(CalendarEvent $event): array
    {
        return [
            'id' => (string) $event->getId()?->toRfc4122(),
            'mod' => (string) ($event->getUpdatedAt()?->getTimestamp() ?? 0),
            'flags' => 0,
            'star' => 0,
        ];
    }

    public function buildSyncAppointment(CalendarEvent $event): \SyncAppointment
    {
        $appointment = new \SyncAppointment();
        $appointment->subject = $event->getTitle();
        $appointment->alldayevent = $event->isAllDay() ? 1 : 0;
        $appointment->starttime = $event->getStartAt()->getTimestamp();

        if (null !== $event->getEndAt()) {
            $appointment->endtime = $event->getEndAt()->getTimestamp();
        }

        if (null !== $event->getLocation() && '' !== $event->getLocation()) {
            $appointment->location = $event->getLocation();
        }

        $this->assignDescription($appointment, $event->getDescription());

        if (null !== $event->getUid() && '' !== $event->getUid()) {
            $appointment->uid = $event->getUid();
        }

        if (null !== $event->getDtstamp()) {
            $appointment->dtstamp = $event->getDtstamp()->getTimestamp();
        }

        if (null !== $event->getBusyStatus()) {
            $appointment->busystatus = $event->getBusyStatus();
        }

        if (null !== $event->getSensitivity()) {
            $appointment->sensitivity = $event->getSensitivity();
        }

        if (null !== $event->getReminder()) {
            $appointment->reminder = $event->getReminder();
        }

        if (null !== $event->getOrganizerName() && '' !== $event->getOrganizerName()) {
            $appointment->organizername = $event->getOrganizerName();
        }

        if (null !== $event->getOrganizerEmail() && '' !== $event->getOrganizerEmail()) {
            $appointment->organizeremail = $event->getOrganizerEmail();
        }

        if (null !== $event->getMeetingStatus()) {
            $appointment->meetingstatus = $event->getMeetingStatus();
        }

        if (null !== $event->getResponseType()) {
            $appointment->responsetype = $event->getResponseType();
        }

        if (null !== $event->getResponseRequested()) {
            $appointment->responserequested = $event->getResponseRequested() ? 1 : 0;
        }

        if (null !== $event->getDisallowNewTimeProposal()) {
            $appointment->disallownewtimeprop = $event->getDisallowNewTimeProposal() ? 1 : 0;
        }

        if (null !== $event->getOnlineMeetingConfLink() && '' !== $event->getOnlineMeetingConfLink()) {
            $appointment->onlineMeetingConfLink = $event->getOnlineMeetingConfLink();
        }

        if (null !== $event->getOnlineMeetingExternalLink() && '' !== $event->getOnlineMeetingExternalLink()) {
            $appointment->onlineMeetingExternalLink = $event->getOnlineMeetingExternalLink();
        }

        $categories = $event->getCategories();

        if (null !== $categories && [] !== $categories) {
            $appointment->categories = $categories;
        }

        $appointment->timezone = $this->timezoneBlob(
            $event->getTimezone() ?? date_default_timezone_get(),
        );

        if (null !== $event->getRecurrenceType()) {
            $appointment->recurrence = $this->buildRecurrence($event);
        }

        $this->assignAttendees($appointment, $event->getAttendees());
        $this->assignExceptions($appointment, $event);

        return $appointment;
    }

    public function applySyncAppointment(CalendarEvent $event, \SyncAppointment $appointment): void
    {
        if (isset($appointment->subject)) {
            $title = trim(is_string($appointment->subject) ? $appointment->subject : '');

            if ('' !== $title) {
                $event->setTitle($title);
            }
        }

        if (isset($appointment->starttime)) {
            $event->setStartAt($this->fromTimestamp($appointment->starttime));
        }

        if (isset($appointment->endtime)) {
            $event->setEndAt($this->fromTimestamp($appointment->endtime));
        }

        if (isset($appointment->alldayevent)) {
            $event->setIsAllDay((bool) $appointment->alldayevent);
        }

        if (isset($appointment->location)) {
            $location = trim(is_string($appointment->location) ? $appointment->location : '');
            $event->setLocation('' !== $location ? $location : null);
        }

        $description = $this->descriptionOrNull($appointment);

        if (false !== $description) {
            $event->setDescription($description);
        }

        if (isset($appointment->timezone) && is_string($appointment->timezone) && '' !== $appointment->timezone) {
            $event->setTimezone($this->timezoneFromBlob($appointment->timezone));
        }

        if (isset($appointment->uid) && is_string($appointment->uid) && '' !== trim($appointment->uid)) {
            $event->setUid(trim($appointment->uid));
        }

        if (isset($appointment->dtstamp)) {
            $event->setDtstamp($this->fromTimestamp($appointment->dtstamp));
        }

        if (isset($appointment->busystatus)) {
            $event->setBusyStatus($this->intOrNull($appointment->busystatus));
        }

        if (isset($appointment->sensitivity)) {
            $event->setSensitivity($this->intOrNull($appointment->sensitivity));
        }

        if (isset($appointment->reminder)) {
            $event->setReminder($this->intOrNull($appointment->reminder));
        }

        if (isset($appointment->organizername)) {
            $organizerName = trim(is_string($appointment->organizername) ? $appointment->organizername : '');
            $event->setOrganizerName('' !== $organizerName ? $organizerName : null);
        }

        if (isset($appointment->organizeremail)) {
            $organizerEmail = trim(is_string($appointment->organizeremail) ? $appointment->organizeremail : '');
            $event->setOrganizerEmail('' !== $organizerEmail ? $organizerEmail : null);
        }

        if (isset($appointment->meetingstatus)) {
            $event->setMeetingStatus($this->intOrNull($appointment->meetingstatus));
        }

        if (isset($appointment->responsetype)) {
            $event->setResponseType($this->intOrNull($appointment->responsetype));
        }

        if (isset($appointment->responserequested)) {
            $event->setResponseRequested((bool) $appointment->responserequested);
        }

        if (isset($appointment->disallownewtimeprop)) {
            $event->setDisallowNewTimeProposal((bool) $appointment->disallownewtimeprop);
        }

        if (isset($appointment->onlineMeetingConfLink)) {
            $link = trim(is_string($appointment->onlineMeetingConfLink) ? $appointment->onlineMeetingConfLink : '');
            $event->setOnlineMeetingConfLink('' !== $link ? $link : null);
        }

        if (isset($appointment->onlineMeetingExternalLink)) {
            $link = trim(is_string($appointment->onlineMeetingExternalLink) ? $appointment->onlineMeetingExternalLink : '');
            $event->setOnlineMeetingExternalLink('' !== $link ? $link : null);
        }

        if (isset($appointment->categories)) {
            $event->setCategories($this->stringListOrNull($appointment->categories));
        }

        $this->applyRecurrence($event, $appointment);
        $this->applyAttendees($event, $appointment);
        $this->applyExceptions($event, $appointment);
    }

    private function buildRecurrence(CalendarEvent $event): \SyncRecurrence
    {
        $recurrence = new \SyncRecurrence();
        $recurrence->type = $event->getRecurrenceType() ?? 0;

        if (null !== $event->getRecurrenceInterval() && $event->getRecurrenceInterval() > 1) {
            $recurrence->interval = $event->getRecurrenceInterval();
        }

        if (null !== $event->getRecurrenceUntil()) {
            $recurrence->until = $event->getRecurrenceUntil()->getTimestamp();
        }

        if (null !== $event->getRecurrenceOccurrences()) {
            $recurrence->occurrences = $event->getRecurrenceOccurrences();
        }

        if (null !== $event->getRecurrenceDayOfWeek()) {
            $recurrence->dayofweek = $event->getRecurrenceDayOfWeek();
        }

        if (null !== $event->getRecurrenceDayOfMonth()) {
            $recurrence->dayofmonth = $event->getRecurrenceDayOfMonth();
        }

        if (null !== $event->getRecurrenceWeekOfMonth()) {
            $recurrence->weekofmonth = $event->getRecurrenceWeekOfMonth();
        }

        if (null !== $event->getRecurrenceMonthOfYear()) {
            $recurrence->monthofyear = $event->getRecurrenceMonthOfYear();
        }

        if (null !== $event->getRecurrenceCalendarType()) {
            $recurrence->calendartype = $event->getRecurrenceCalendarType();
        }

        if (null !== $event->getRecurrenceFirstDayOfWeek()) {
            $recurrence->firstdayofweek = $event->getRecurrenceFirstDayOfWeek();
        }

        return $recurrence;
    }

    private function applyRecurrence(CalendarEvent $event, \SyncAppointment $appointment): void
    {
        if (!isset($appointment->recurrence) || !$appointment->recurrence instanceof \SyncRecurrence) {
            return;
        }

        $recurrence = $appointment->recurrence;
        $event->setRecurrenceType($this->intOrNull($recurrence->type ?? null));
        $event->setRecurrenceInterval($this->intOrNull($recurrence->interval ?? null));
        $event->setRecurrenceOccurrences($this->intOrNull($recurrence->occurrences ?? null));

        if (isset($recurrence->until)) {
            $event->setRecurrenceUntil($this->fromTimestamp($recurrence->until));
        } else {
            $event->setRecurrenceUntil(null);
        }

        $event->setRecurrenceDayOfWeek($this->intOrNull($recurrence->dayofweek ?? null));
        $event->setRecurrenceDayOfMonth($this->intOrNull($recurrence->dayofmonth ?? null));
        $event->setRecurrenceWeekOfMonth($this->intOrNull($recurrence->weekofmonth ?? null));
        $event->setRecurrenceMonthOfYear($this->intOrNull($recurrence->monthofyear ?? null));
        $event->setRecurrenceCalendarType($this->intOrNull($recurrence->calendartype ?? null));
        $event->setRecurrenceFirstDayOfWeek($this->intOrNull($recurrence->firstdayofweek ?? null));
    }

    /**
     * @param list<array{name: ?string, email: ?string, type: ?int, status: ?int}>|null $attendees
     */
    private function assignAttendees(\SyncAppointment $appointment, ?array $attendees): void
    {
        if (null === $attendees || [] === $attendees) {
            return;
        }

        $syncAttendees = [];

        foreach ($attendees as $attendee) {
            $syncAttendee = new \SyncAttendee();
            $syncAttendee->name = $attendee['name'];
            $syncAttendee->email = $attendee['email'];

            if (null !== $attendee['type']) {
                $syncAttendee->attendeetype = $attendee['type'];
            }

            if (null !== $attendee['status']) {
                $syncAttendee->attendeestatus = $attendee['status'];
            }

            $syncAttendees[] = $syncAttendee;
        }

        $appointment->attendees = $syncAttendees;
    }

    /**
     * The device sends the complete attendee list on every series change;
     * the stored list is replaced accordingly.
     */
    private function applyAttendees(CalendarEvent $event, \SyncAppointment $appointment): void
    {
        if (!isset($appointment->attendees) || !is_array($appointment->attendees)) {
            return;
        }

        $attendees = [];

        foreach ($appointment->attendees as $attendee) {
            if (!$attendee instanceof \SyncAttendee) {
                continue;
            }

            $attendees[] = [
                'name' => $this->trimmedOrNull($attendee->name ?? null),
                'email' => $this->trimmedOrNull($attendee->email ?? null),
                'type' => $this->intOrNull($attendee->attendeetype ?? null),
                'status' => $this->intOrNull($attendee->attendeestatus ?? null),
            ];
        }

        $event->setAttendees([] === $attendees ? null : $attendees);
    }

    private function assignExceptions(\SyncAppointment $appointment, CalendarEvent $event): void
    {
        if (0 === $event->getExceptions()->count()) {
            return;
        }

        $exceptions = [];

        foreach ($event->getExceptions() as $exception) {
            $syncException = new \SyncAppointmentException();
            $syncException->exceptionstarttime = $exception->getExceptionStartAt()->getTimestamp();
            $syncException->deleted = $exception->isDeleted() ? 1 : 0;

            if ($exception->isDeleted()) {
                $exceptions[] = $syncException;

                continue;
            }

            if (null !== $exception->getTitle()) {
                $syncException->subject = $exception->getTitle();
            }

            if (null !== $exception->getStartAt()) {
                $syncException->starttime = $exception->getStartAt()->getTimestamp();
            }

            if (null !== $exception->getEndAt()) {
                $syncException->endtime = $exception->getEndAt()->getTimestamp();
            }

            $syncException->alldayevent = $exception->isAllDay() ? 1 : 0;

            if (null !== $exception->getLocation() && '' !== $exception->getLocation()) {
                $syncException->location = $exception->getLocation();
            }

            $this->assignExceptionDescription($syncException, $exception->getDescription());

            if (null !== $exception->getBusyStatus()) {
                $syncException->busystatus = $exception->getBusyStatus();
            }

            if (null !== $exception->getReminder()) {
                $syncException->reminder = $exception->getReminder();
            }

            $exceptions[] = $syncException;
        }

        if ([] !== $exceptions) {
            $appointment->exceptions = $exceptions;
        }
    }

    /**
     * Devices replace the whole exception list when a series changes; the
     * stored exceptions are rebuilt from the device state (orphanRemoval
     * drops the previous rows).
     */
    private function applyExceptions(CalendarEvent $event, \SyncAppointment $appointment): void
    {
        if (!isset($appointment->exceptions) || !is_array($appointment->exceptions)) {
            return;
        }

        foreach (array_values($event->getExceptions()->toArray()) as $exception) {
            $event->removeException($exception);
        }

        foreach ($appointment->exceptions as $exception) {
            if (!$exception instanceof \SyncAppointmentException || !isset($exception->exceptionstarttime)) {
                continue;
            }

            $stored = new CalendarEventException();
            $stored->setExceptionStartAt($this->fromTimestamp($exception->exceptionstarttime));
            $stored->setIsDeleted(isset($exception->deleted) && (bool) $exception->deleted);

            if (!$stored->isDeleted()) {
                if (isset($exception->subject) && is_string($exception->subject)) {
                    $title = trim($exception->subject);
                    $stored->setTitle('' !== $title ? $title : null);
                }

                if (isset($exception->starttime)) {
                    $stored->setStartAt($this->fromTimestamp($exception->starttime));
                }

                if (isset($exception->endtime)) {
                    $stored->setEndAt($this->fromTimestamp($exception->endtime));
                }

                if (isset($exception->alldayevent)) {
                    $stored->setIsAllDay((bool) $exception->alldayevent);
                }

                if (isset($exception->location) && is_string($exception->location)) {
                    $location = trim($exception->location);
                    $stored->setLocation('' !== $location ? $location : null);
                }

                $description = $this->descriptionOrNull($exception);

                if (false !== $description) {
                    $stored->setDescription($description);
                }

                if (isset($exception->busystatus)) {
                    $stored->setBusyStatus($this->intOrNull($exception->busystatus));
                }

                if (isset($exception->reminder)) {
                    $stored->setReminder($this->intOrNull($exception->reminder));
                }
            }

            $event->addException($stored);
        }
    }

    /**
     * The description follows the message body conventions: AirSyncBase
     * body from protocol 12 on (the legacy body element is unmapped there),
     * the plain body below.
     */
    private function assignDescription(\SyncAppointment $appointment, ?string $description): void
    {
        if (null === $description || '' === $description) {
            return;
        }

        if (\Request::GetProtocolVersion() >= 12.0) {
            $asbody = new \SyncBaseBody();
            $asbody->type = SYNC_BODYPREFERENCE_PLAIN;
            $asbody->truncated = 0;
            $asbody->data = \StringStreamWrapper::Open($description);
            $asbody->estimatedDataSize = strlen($description);
            $appointment->asbody = $asbody;

            return;
        }

        $appointment->body = $description;
    }

    private function assignExceptionDescription(\SyncAppointmentException $exception, ?string $description): void
    {
        if (null === $description || '' === $description) {
            return;
        }

        if (\Request::GetProtocolVersion() >= 12.0) {
            $asbody = new \SyncBaseBody();
            $asbody->type = SYNC_BODYPREFERENCE_PLAIN;
            $asbody->truncated = 0;
            $asbody->data = \StringStreamWrapper::Open($description);
            $asbody->estimatedDataSize = strlen($description);
            $exception->asbody = $asbody;

            return;
        }

        $exception->body = $description;
    }

    /**
     * Reads the description from whichever body representation the device
     * used. Returns false when the device sent no body at all.
     */
    private function descriptionOrNull(\SyncAppointment $appointment): string|false|null
    {
        if (isset($appointment->asbody) && $appointment->asbody instanceof \SyncBaseBody) {
            $data = $appointment->asbody->data;

            if (is_resource($data)) {
                $data = (string) stream_get_contents($data);
            }

            return is_string($data) && '' !== trim($data) ? $data : null;
        }

        if (isset($appointment->body)) {
            $value = is_string($appointment->body) ? trim($appointment->body) : '';

            return '' !== $value ? $value : null;
        }

        return false;
    }

    private function timezoneBlob(string $timezoneName): string
    {
        return base64_encode(\TimezoneUtil::GetSyncBlobFromTZ(
            \TimezoneUtil::GetFullTZFromTZName($timezoneName),
        ));
    }

    private function timezoneFromBlob(string $blob): ?string
    {
        $raw = base64_decode($blob, true);

        // A full TZ struct is 172 bytes (4 + 64 + 16 + 4 + 64 + 16 + 4);
        // anything shorter is garbage and yields no usable timezone.
        if (false === $raw || strlen($raw) < 172) {
            return null;
        }

        $unpacked = unpack('lbias', substr($raw, 0, 4));
        \assert(is_array($unpacked) && is_int($unpacked['bias']));

        // The bias is the minutes to ADD to local time to get UTC, so the
        // UTC offset is its negative.
        $offsetMinutes = -1 * $unpacked['bias'];

        return sprintf('%s%02d:%02d', $offsetMinutes >= 0 ? '+' : '-', intdiv(abs($offsetMinutes), 60), abs($offsetMinutes) % 60);
    }

    private function fromTimestamp(mixed $timestamp): \DateTimeImmutable
    {
        return new \DateTimeImmutable()->setTimestamp(is_numeric($timestamp) ? (int) $timestamp : 0);
    }

    private function intOrNull(mixed $value): ?int
    {
        return is_int($value) ? $value : (is_numeric($value) ? (int) $value : null);
    }

    /**
     * @return list<string>|null null clears the list, non-arrays are ignored
     */
    private function stringListOrNull(mixed $value): ?array
    {
        if (!is_array($value)) {
            return null;
        }

        $items = [];

        foreach ($value as $item) {
            if (is_string($item) && '' !== trim($item)) {
                $items[] = trim($item);
            }
        }

        return [] === $items ? null : $items;
    }

    private function trimmedOrNull(mixed $value): ?string
    {
        return is_string($value) && '' !== trim($value) ? trim($value) : null;
    }
}
